  methods: {
    async updateData() {
      const res = await reportAgent({ type: this.currentValue, agent: this.$route.query.agent })
      this.totalData = [{ label: '总充值', value: res.allcz }, { label: '总提现', value: res.alltx }, { label: '总余额', value: res.mons }, { label: '未领取返点', value: res.backmons }
      ]
      this.totalData1 = [{ label: '游戏输赢', value: res.gamewin }, { label: '游戏手续费', value: res.gamesxf }, { label: '官方收取比例', value: res.gamesxfbl }
      ]
      this.formData = [{ label: '充值手续费', mons: res.czsxf, percent: res.czsxfbl }, { label: '提现手续费', mons: res.txsxf, percent: res.txsxfbl }, { label: '管理费金额', mons: res.glfmons, percent: res.glfbl }]
      this.fhbl = res.fhbl
      this.allwin = res.allwin
      this.fhmons = res.fhmons
    },
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    toDetail() {
      this.$router.push({ path: '/agentDetail', query: { agent: this.$route.query.agent, type: this.currentValue }})
    },
